/**
 * W1 init 模板常量——由 scripts/gen-init-templates.cjs 从已验证最终形态程序化提取（勿手改）。
 * 占位符在运行时由 init.ts 按 fulgur.config.ts 的 apps/env/deploy 值替换。
 */

export const T_FULGUR_PAGES = "/**\n * 联邦页面通道：27 页后台菜单路由映射表 + URL 匹配器 + 页面组件工厂\n *\n * 后台菜单把 /flowable/**（21 页）与 /lowcode/**（6 页）配置给 qiankun 子应用；\n * 联邦模式下这些路径由本表解析为「远程 exposes 模块」，经 defineAsyncComponent\n * 直渲染进宿主布局内容区（LayoutContent 联邦分支）。\n *\n * 兼容两个 URL 空间：dev 直链 /flowable/** 与 prod /main/flowable/**\n * （vue-router base=/main 剥离后同一路由空间）；:id/:code 参数段通配。\n */\nimport { defineAsyncComponent, h } from 'vue';\nimport { loadRemote } from 'virtual:fulgur-runtime';\nimport { defineFulgurPages } from '@fulgur/federation/pages';\nimport remoteSchema from 'virtual:fulgur-remote-schema';\nimport { fulgurBridge } from './fulgurBridge';\n\nexport interface FulgurPageRoute {\n  /** 宿主路由路径（/flowable、/lowcode 原生空间，与后台菜单 url 一致，参数段用 :xx） */\n  route: string;\n  /** 原子应用路由 name——命名跳转（push({name})）依赖宿主挂同名路由 */\n  name?: string;\n  /** 远程模块 spec（缺省 = 按 route 前缀推断 exposes 键 pages/<route 去前缀去参>） */\n  spec?: string;\n  /** 页签中文标题（与后台菜单业务名一致） */\n  title?: string;\n}\n\n/** 27 页映射（bpm 20 条覆盖 21 菜单——create/update/copy 共用 model/form；lowcode 6 条）\n *  D.2：defineFulgurPages 校验（剥参收敛冲突/遮蔽/重复等，带参路由必须显式 spec） */\nexport const FULGUR_PAGES: FulgurPageRoute[] = defineFulgurPages(\n  [\n    { route: '/flowable/bpm/task/todo', name: 'BpmTodoTask', title: '待办任务' },\n    { route: '/flowable/bpm/task/done', name: 'BpmDoneTask', title: '已办任务' },\n    { route: '/flowable/bpm/task/my', name: 'BpmProcessInstanceMy', title: '我的流程' },\n    { route: '/flowable/bpm/task/copy', name: 'BpmProcessInstanceCopy', title: '抄送我的' },\n    { route: '/flowable/bpm/task/create', name: 'BpmProcessInstanceCreate', title: '发起流程' },\n    {\n      route: '/flowable/bpm/process-instance/detail',\n      name: 'BpmProcessInstanceDetail',\n      title: '流程详情',\n    },\n    { route: '/flowable/bpm/manager/action', name: 'BpmModelAction', title: '审批操作' },\n    { route: '/flowable/bpm/manager/model', name: 'BpmModel', title: '流程模型' },\n    { route: '/flowable/bpm/manager/model/create', name: 'BpmModelCreate', title: '创建流程' },\n    {\n      // bpm 原路由单条 :type/:id（type=update|copy|definition），命名跳转带 params.type，\n      // 拆成 update/:id + copy/:id 两条会丢弃 type（复制变更新，数据风险）。\n      // spec 显式覆盖：参数段剥离会把 expose 键错误收敛成列表页（pages/bpm/manager/model），\n      // 而 update/copy/definition 三个 expose 指向同一表单文件、行为由 route.params.type 驱动\n      route: '/flowable/bpm/manager/model/:type/:id',\n      name: 'BpmModelUpdate',\n      spec: 'pages/bpm/manager/model/update',\n      title: '修改流程',\n    },\n    { route: '/flowable/bpm/manager/form', name: 'BpmForm', title: '流程表单' },\n    { route: '/flowable/bpm/manager/form/edit', name: 'BpmFormEditor', title: '表单设计' },\n    { route: '/flowable/bpm/manager/category', name: 'BpmCategory', title: '流程分类' },\n    { route: '/flowable/bpm/manager/user-group', name: 'BpmUserGroup', title: '用户分组' },\n    { route: '/flowable/bpm/manager/process-listener', name: 'BpmProcessListener', title: '流程监听器' },\n    { route: '/flowable/bpm/manager/process-expression', name: 'BpmProcessExpression', title: '流程表达式' },\n    {\n      route: '/flowable/bpm/manager/process-instance/manager',\n      name: 'BpmProcessInstanceManager',\n      title: '流程实例管理',\n    },\n    { route: '/flowable/bpm/manager/process-tasnk', name: 'BpmManagerTask', title: '任务管理' },\n    { route: '/flowable/bpm/manager/definition', name: 'BpmProcessDefinition', title: '流程定义' },\n    { route: '/flowable/bpm/process-instance/report', name: 'BpmProcessInstanceReport', title: '流程报表' },\n    { route: '/lowcode/lowdev/formDesign', name: 'LowcodeFormDesign', title: '表单设计' },\n    { route: '/lowcode/lowdev/reportDesign', name: 'LowcodeReportDesign', title: '报表设计' },\n    { route: '/lowcode/lowdev/graphReportDesign', name: 'LowcodeGraphReportDesign', title: '图形报表' },\n    { route: '/lowcode/lowdev/moduleDesign', name: 'LowcodeModuleDesign', title: '模块设计' },\n    { route: '/lowcode/lowdev/reportTest/:code', name: 'ReportTest', title: '报表功能测试' },\n    { route: '/lowcode/form/external/:type/:id', name: 'formExternal', title: '外部表单' },\n  ],\n  {\n    // D.2：与下方 exposeKeyOfRoute 同款推导规则；schema（dev）供 spec 存在性校验\n    deriveSpec: (route) =>\n      'pages/' +\n      route\n        .replace(/^\\/(flowable|lowcode)\\//, '')\n        .split('/')\n        .filter((seg) => !seg.startsWith(':'))\n        .join('/'),\n    remotes: { '/flowable/': '__BPM_NAME__', '/lowcode/': '__LOWCODE_NAME__' },\n    schema: remoteSchema,\n  },\n);\n\n/** 路由前缀 → remote 名（与 admin vite.config remotes 键一致） */\nfunction remoteOfRoute(route: string): string {\n  return route.startsWith('/lowcode/') ? '__LOWCODE_NAME__' : '__BPM_NAME__';\n}\n\n/** 路由路径 → exposes 键（pages/<去前缀去参数段>） */\nfunction exposeKeyOfRoute(route: string): string {\n  const withoutPrefix = route.replace(/^\\/(flowable|lowcode)\\//, '');\n  const withoutParams = withoutPrefix\n    .split('/')\n    .filter((seg) => !seg.startsWith(':'))\n    .join('/');\n  return `pages/${withoutParams}`;\n}\n\n/** 路径段匹配：支持 :param 通配，返回捕获参数；不匹配返回 null */\nfunction matchSegments(pattern: string, path: string): Record<string, string> | null {\n  const patSegs = pattern.split('/').filter(Boolean);\n  const pathSegs = path.split('/').filter(Boolean);\n  if (patSegs.length !== pathSegs.length) return null;\n  const params: Record<string, string> = {};\n  for (let i = 0; i < patSegs.length; i++) {\n    const seg = patSegs[i];\n    if (seg.startsWith(':')) {\n      params[seg.slice(1)] = decodeURIComponent(pathSegs[i]);\n    } else if (seg !== pathSegs[i]) {\n      return null;\n    }\n  }\n  return params;\n}\n\n/**\n * URL 匹配器：把宿主路径解析为联邦页面条目 + 捕获参数。\n * 兼容 /flowable/**（dev 直链与 router path 空间）与 /main/flowable/**（prod base 前缀直链）。\n */\nexport function resolveFulgurPageFromPath(\n  path: string,\n): { page: FulgurPageRoute; remote: string; spec: string; params: Record<string, string> } | null {\n  const clean = path.replace(/^\\/main(?=\\/)/, '').replace(/\\/+$/, '') || '/';\n  for (const page of FULGUR_PAGES) {\n    const params = matchSegments(page.route, clean);\n    if (params) {\n      const remote = remoteOfRoute(page.route);\n      const spec = `${remote}/${page.spec ?? exposeKeyOfRoute(page.route)}`;\n      return { page, remote, spec, params };\n    }\n  }\n  return null;\n}\n\n/** federatedBoot 按 remote 记忆化；失败显式抛错（H3 零兜底，禁止 warn「跳过」） */\nconst bootedRemotes = new Map<string, Promise<void>>();\n\nexport function bootRemoteOnce(remote: string): Promise<void> {\n  if (!bootedRemotes.has(remote)) {\n    const p = (async () => {\n      try {\n        const mod: any = await loadRemote(`${remote}/federatedBoot`);\n        const boot = mod?.default ?? mod?.federatedBoot ?? mod;\n        if (typeof boot === 'function') {\n          await boot();\n        }\n      } catch (e: any) {\n        bootedRemotes.delete(remote);\n        throw new Error(\n          `[fulgur] federatedBoot 初始化失败（remote=${remote}）：${String(e?.message ?? e)}` +\n            `。请检查 remote dev server 是否运行（MFU-001）与 exposes 是否包含 ./federatedBoot（MFU-006）`,\n        );\n      }\n    })();\n    bootedRemotes.set(remote, p);\n  }\n  return bootedRemotes.get(remote)!;\n}\n\n/** expose 组件按 spec 缓存，避免 defineAsyncComponent 重复创建导致反复重挂载 */\nconst compCache = new Map<string, ReturnType<typeof defineAsyncComponent>>();\n\n/**\n * 页面组件工厂：loadRemote 前先同步桥接（token/user 写入子应用期望的缓存形态），\n * 再按 remote 记忆化执行 federatedBoot，最后加载页面组件\n */\nexport function fulgurPageComponent(spec: string, remote: string) {\n  if (!compCache.has(spec)) {\n    compCache.set(\n      spec,\n      defineAsyncComponent({\n        loader: async () => {\n          fulgurBridge();\n          await bootRemoteOnce(remote);\n          const mod: any = await loadRemote(spec);\n          const comp = mod?.default ?? mod;\n          if (!comp) {\n            throw new Error(`[fulgur] 远程模块 \"${spec}\" 未导出组件（MFU-006 语义：核对 exposes 键名）`);\n          }\n          return comp;\n        },\n        errorComponent: (errProps) =>\n          h('div', { style: 'padding:32px;color:#e65050;font-size:14px;line-height:1.8' }, [\n            h('h3', { style: 'margin:0 0 8px' }, `联邦页面加载失败：${spec}`),\n            h('pre', { style: 'white-space:pre-wrap' }, String(errProps.error)),\n          ]),\n      }) as any,\n    );\n  }\n  return compCache.get(spec)!;\n}\n";

export const T_FULGUR_BRIDGE = "/**\n * 联邦桥：乾坤 props 桥的联邦等价物\n *\n * 乾坤时代子应用 mount 时收到 props（qiankun/state.ts getProps()），render() 把\n * token/user 写入各自体系的 localStorage 缓存并挂 window.mainAppProps/mainRouter。\n * 联邦模式没有 mount 生命周期，本模块在远程页面组件 loadRemote 前同步完成同等写入：\n *\n * - bpm（yudao 体系）：wsCache 'ACCESS_TOKEN'/'REFRESH_TOKEN'\n * - lowcode（jeelowcode+yudao 混合体）：wsCache 'lowCodeuser'（permissions 为对象 map，\n *   hasPermi 指令依赖）+ 同一套 token 键\n * - window.mainAppProps / mainRouter：与 getProps() 形态一致，供流程详情等页面读取\n *   formUrl/baseUrl（脱离宿主的 iframe 用法也依赖它判断 realm）\n * - window.__FULGUR_HOST_APP__：宿主 app 实例（远程 federatedBoot 注册全局组件用）\n *\n * wsCache 形态 = web-storage-cache 序列化（{c,e,v} 双重序列化），bpm/lowcode 的\n * useCache（WebStorageCache.get）依赖该格式反序列化。admin 自身无 web-storage-cache\n * 依赖，这里按其源码格式手写写入（c=创建时间戳、e=过期时间戳、v=JSON 序列化值）。\n */\nimport { useUserStore } from '/@/store/modules/user';\nimport { usePermissionStore } from '/@/store/modules/permission';\nimport { getToken } from '/@/utils/auth';\nimport { app as hostApp, store } from '/@/store';\nimport { router } from '/@/router';\nimport activitiesEvents, { mainEvents } from '/@/utils/activitiesEvents';\nimport { provideGlobalConfig } from 'element-plus';\nimport zhCn from 'element-plus/es/locale/lang/zh-cn';\n\n/** web-storage-cache 同款写入（_maxExpireDate = 9999-12-31，v 二次 JSON 序列化） */\nfunction writeWsCache(key: string, value: unknown) {\n  try {\n    const item = {\n      c: Date.now(),\n      e: new Date('Fri, 31 Dec 9999 23:59:59 UTC').getTime(),\n      v: JSON.stringify(value),\n    };\n    window.localStorage.setItem(key, JSON.stringify(item));\n  } catch (e) {\n    console.error('[fulgur] wsCache 写入失败:', key, e);\n  }\n}\n\n/** 权限码 → 对象 map（lowcode hasPermi 指令按 map 键判定） */\nfunction toPermissionMap(codes: string[] | undefined): Record<string, boolean> {\n  const map: Record<string, boolean> = {};\n  for (const c of codes ?? []) map[c] = true;\n  return map;\n}\n\n/** 已执行过则跳过（幂等：登录态变化由重新登录流程触发全量重写） */\nlet bridged = false;\n\nexport function fulgurBridge() {\n  if (bridged) return;\n  bridged = true;\n\n  const userStore = useUserStore();\n  const permissionStore = usePermissionStore();\n  const token = getToken();\n  const user = userStore.getUserInfo;\n\n  // ---- bpm（yudao 体系）：token 写入其 useCache 约定键 ----\n  if (token) {\n    writeWsCache('ACCESS_TOKEN', token);\n    writeWsCache('REFRESH_TOKEN', token);\n  }\n\n  // ---- lowcode（jeelowcode 体系）：用户信息 + 权限对象 map ----\n  if (user) {\n    // admin 的 getPermCodeList 是 state 数组（非方法）\n    const rawCodes = (permissionStore as any)?.getPermCodeList ?? (permissionStore as any)?.permCodeList ?? [];\n    const permCodes = Array.isArray(rawCodes) ? rawCodes : typeof rawCodes === 'function' ? rawCodes() : [];\n    const userInfo = {\n      ...(user as Record<string, any>),\n      id: Number((user as any)?.id),\n      permissions: toPermissionMap(permCodes),\n      jeeLowCodepermissions: {},\n    };\n    writeWsCache('lowCodeuser', userInfo);\n  }\n\n  // ---- window 桥（与 qiankun getProps() 形态一致）----\n  const mainAppProps = {\n    publicPath: '/',\n    token,\n    getToken,\n    store,\n    router,\n    user,\n    formUrl: window.location.origin + '/main/FormRouterPage?hideSider=true&hideHeader=true&hideMultiTabs=true&',\n    baseUrl: window.location.origin + '/main',\n    bpmEvents: activitiesEvents,\n    mainEvents,\n  };\n  (window as any).mainAppProps = mainAppProps;\n  (window as any).mainRouter = router;\n  // 宿主 app 实例：子应用 federatedBoot 把全局组件/指令注册到宿主 app 上\n  //（乾坤 mount 期等价行为；同 realm 直接引用，无序列化问题）\n  if (hostApp) {\n    (window as any).__FULGUR_HOST_APP__ = hostApp;\n    // EP 全局 locale（宿主副本）：远程页（avue-crud 等）经宿主全局组件注册表解析到的\n    // el-pagination 是宿主自己的 EP 副本，其 localeContextKey 与远程副本不同——宿主侧\n    // 也注入一份中文 locale，保证无论解析到哪个副本分页都是「共 N 条」\n    provideGlobalConfig({ locale: zhCn }, hostApp);\n  }\n}\n\nexport default fulgurBridge;\n";

export const T_FULGUR_DEMO = "<template>\n  <div class=\"p-24px\">\n    <PageWrapper title=\"联邦演示页（fulgur-demo）\" contentBackground>\n      <div class=\"mb-16px text-14px text-gray-500\">\n        本页为免登录演示路由（meta.ignoreAuth）：双远程组件经联邦直渲染——\n        TaskCard 来自 __BPM_NAME__（/flowable），InfoCard 来自 __LOWCODE_NAME__（/lowcode）。\n        点击按钮验证跨应用组件加载与响应式交互。\n      </div>\n      <div class=\"flex flex-wrap gap-16px\">\n        <TaskCard v-if=\"taskCardReady\" />\n        <InfoCard v-if=\"infoCardReady\" />\n      </div>\n      <div class=\"mt-16px\">\n        <Alert\n          v-if=\"loadError\"\n          type=\"error\"\n          :message=\"'远程组件加载失败（显式报错，无兜底）'\"\n          :description=\"loadError\"\n          show-icon\n        />\n      </div>\n      <!-- 联邦运行时实测信息：remotes 状态 + shared 协商表（manual §5 证据展示，数据实时读 runtime） -->\n      <div class=\"mt-24px runtime-info\">\n        <h3 class=\"info-title\">联邦运行时信息（实测读取 window.__FULGUR_INFO__ / __FULGUR_SCOPE__）</h3>\n        <table class=\"info-table\">\n          <thead>\n            <tr><th>remote</th><th>entry</th><th>状态</th></tr>\n          </thead>\n          <tbody>\n            <tr v-for=\"r in remotesInfo\" :key=\"r.name\">\n              <td>{{ r.name }}</td>\n              <td>{{ r.entry }}</td>\n              <td :class=\"r.status === 'loaded' ? 'ok' : 'bad'\">{{ r.status }}</td>\n            </tr>\n          </tbody>\n        </table>\n        <table class=\"info-table\">\n          <thead>\n            <tr><th>shared 键</th><th>协商条目（version ← 提供方）</th></tr>\n          </thead>\n          <tbody>\n            <tr v-for=\"s in sharedInfo\" :key=\"s.key\">\n              <td>{{ s.key }}</td>\n              <td>{{ s.entries }}</td>\n            </tr>\n          </tbody>\n        </table>\n        <p class=\"info-hint\">多版本条目并存，消费方按 requiredVersion 取最高满足版本；数据由运行时注册表实时读取。</p>\n      </div>\n    </PageWrapper>\n  </div>\n</template>\n\n<script lang=\"ts\" setup name=\"FulgurDemo\">\n  import { defineAsyncComponent, ref, onMounted, onUnmounted } from 'vue';\n  import { PageWrapper } from '/@/components/Page';\n  import { Alert } from 'ant-design-vue';\n  import { loadRemote } from 'virtual:fulgur-runtime';\n  import { fulgurBridge } from '/@/qiankun/fulgurBridge';\n\n  defineOptions({ name: 'FulgurDemo' });\n\n  // 桥接先行：远程组件可能读取 token/user 缓存\n  fulgurBridge();\n\n  const TaskCard = defineAsyncComponent(async () => {\n    const mod: any = await loadRemote('__BPM_NAME__/TaskCard');\n    return mod?.default ?? mod;\n  });\n  const InfoCard = defineAsyncComponent(async () => {\n    const mod: any = await loadRemote('__LOWCODE_NAME__/InfoCard');\n    return mod?.default ?? mod;\n  });\n\n  const taskCardReady = ref(true);\n  const infoCardReady = ref(true);\n  const loadError = ref('');\n  const onError = (e: PromiseRejectionEvent) => {\n    loadError.value = String(e.reason?.message ?? e.reason);\n    taskCardReady.value = false;\n    infoCardReady.value = false;\n  };\n\n  // remotes 状态 + shared 协商表：轮询 runtime 注册表直到两个 remote 都 loaded（注册表非响应式，读快照）\n  const remotesInfo = ref<{ name: string; entry: string; status: string }[]>([]);\n  const sharedInfo = ref<{ key: string; entries: string }[]>([]);\n  const readRuntimeInfo = () => {\n    const info = (window as any).__FULGUR_INFO__;\n    const scope = (window as any).__FULGUR_SCOPE__;\n    const remotes = info?.remotes ?? {};\n    remotesInfo.value = Object.entries(remotes).map(([name, v]: [string, any]) => ({\n      name,\n      entry: String(v?.entry ?? ''),\n      status: String(v?.status ?? 'unknown')\n    }));\n    const defScope = scope?.default ?? {};\n    sharedInfo.value = Object.entries(defScope).map(([key, entries]: [string, any]) => ({\n      key,\n      entries: Object.values(entries ?? {})\n        .map((e: any) => `${e.version} ← ${e.from}`)\n        .join('、')\n    }));\n    return Object.values(remotes).every((v: any) => v?.status === 'loaded');\n  };\n  let pollTimer: ReturnType<typeof setInterval> | undefined;\n  onMounted(() => {\n    window.addEventListener('unhandledrejection', onError);\n    pollTimer = setInterval(() => {\n      if (readRuntimeInfo()) {\n        clearInterval(pollTimer);\n        pollTimer = undefined;\n      }\n    }, 500);\n    readRuntimeInfo();\n  });\n  onUnmounted(() => {\n    window.removeEventListener('unhandledrejection', onError);\n    if (pollTimer) clearInterval(pollTimer);\n  });\n</script>\n\n<style lang=\"less\" scoped>\n  .runtime-info {\n    padding: 16px;\n    border: 1px solid #ebeef5;\n    border-radius: 8px;\n    background: #fafafa;\n  }\n\n  .info-title {\n    margin: 0 0 12px;\n    font-size: 15px;\n    font-weight: 600;\n  }\n\n  .info-table {\n    width: 100%;\n    margin-bottom: 12px;\n    border-collapse: collapse;\n    font-size: 13px;\n    background: #fff;\n\n    th,\n    td {\n      border: 1px solid #ebeef5;\n      padding: 6px 10px;\n      text-align: left;\n    }\n\n    th {\n      background: #f5f7fa;\n      color: #606266;\n    }\n\n    .ok {\n      color: #67c23a;\n    }\n\n    .bad {\n      color: #f56c6c;\n    }\n  }\n\n  .info-hint {\n    margin: 0;\n    color: #909399;\n    font-size: 12px;\n  }\n</style>\n";

export const T_BPM_BOOT = "/**\n * 联邦启动初始化（bpm 版，乾坤 mount 期行为的联邦等价物）\n *\n * 乾坤时代 bpm 整应用启动：路由守卫 setUserInfoAction()（用户/权限集，⚠️ 该方法会级联\n * 构建 bpm 自身路由表 → 与宿主路由撞名 Redirect）+ setDictMap()（字典）。\n * 联邦模式下改为最小状态注入：\n * - permissions 直接置通配集合（testbed admin 全权限语义；hasPermi/checkPermi 走 .has()）\n * - 字典走 dictStore.setDictMap()（纯 API 拉取，无路由副作用）\n *\n * token 由宿主 fulgurBridge 预先写入本应用 useCache 约定键（ACCESS_TOKEN 等）。\n * ⚠️ store 必须挂到宿主 app 安装的 pinia 实例（mainAppProps.store）——联邦页面在\n * 宿主组件树内 useUserStore() 无参调用时解析的就是这份。memoized；失败显式抛错（H3）。\n */\nimport { useUserStore } from '@/store/modules/user';\nimport { useDictStore } from '@/store/modules/dict';\n\nlet booted: Promise<void> | null = null;\n\nexport async function federatedBoot(): Promise<void> {\n  if (!booted) {\n    booted = (async () => {\n      const mainStore = (globalThis as any).mainAppProps?.store;\n      if (!mainStore) {\n        throw new Error(\n          '[federatedBoot] 宿主 pinia 不可用（mainAppProps.store 未写入），无法初始化 user/dict store',\n        );\n      }\n      const userStore = useUserStore(mainStore);\n      const dictStore = useDictStore(mainStore);\n      // 最小权限集：hasPermi/checkPermi 的 .has() 命中通配即放行（testbed admin 全权限语义）\n      userStore.permissions = new Set<string>(['*', '*:*:*']);\n      // 字典：纯 API 拉取写入 store，无路由副作用\n      await dictStore.setDictMap();\n    })().catch((e) => {\n      booted = null;\n      throw e;\n    });\n  }\n  return booted;\n}\n\nexport default federatedBoot;\n";

export const T_BPM_TASKCARD = "<template>\n  <div class=\"fulgur-task-card\">\n    <div class=\"card-header\">\n      <span>__BPM_NAME__ 远程组件 TaskCard</span>\n      <span class=\"tag\">联邦直渲染</span>\n    </div>\n    <div class=\"progress-track\">\n      <div class=\"progress-bar\" :style=\"{ width: progress + '%' }\"></div>\n    </div>\n    <div class=\"progress-text\">{{ progress }}%</div>\n    <div class=\"actions\">\n      <button class=\"btn primary\" @click=\"handleAdvance\">推进 10%</button>\n      <button class=\"btn\" @click=\"handleReset\">重置</button>\n    </div>\n    <p class=\"hint\">本组件来自 cku-__BPM_NAME__（/flowable），验证跨应用组件加载与响应式交互。</p>\n  </div>\n</template>\n\n<script lang=\"ts\" setup>\n  import { ref } from 'vue'\n\n  // 注意：exposes 演示组件保持纯 Vue + 原生元素（DESIGN 已知差异 #4 规避①：\n  // 避免依赖宿主/远程任意一方 UI 库的 prebundle，防多实例混用 Illegal constructor）\n  const progress = ref(0)\n\n  const handleAdvance = () => {\n    progress.value = Math.min(100, progress.value + 10)\n  }\n\n  const handleReset = () => {\n    progress.value = 0\n  }\n</script>\n\n<style scoped>\n  .fulgur-task-card {\n    width: 420px;\n    padding: 16px;\n    border: 1px solid #dcdfe6;\n    border-radius: 8px;\n    background: #fff;\n    font-size: 14px;\n  }\n  .card-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    font-weight: 600;\n  }\n  .tag {\n    padding: 1px 8px;\n    border-radius: 4px;\n    background: #f0f9eb;\n    color: #67c23a;\n    font-size: 12px;\n    font-weight: 400;\n  }\n  .progress-track {\n    margin-top: 16px;\n    height: 12px;\n    border-radius: 6px;\n    background: #ebeef5;\n    overflow: hidden;\n  }\n  .progress-bar {\n    height: 100%;\n    border-radius: 6px;\n    background: linear-gradient(90deg, #409eff, #67c23a);\n    transition: width 0.3s ease;\n  }\n  .progress-text {\n    margin-top: 6px;\n    color: #606266;\n    font-size: 12px;\n  }\n  .actions {\n    margin-top: 14px;\n    display: flex;\n    gap: 8px;\n  }\n  .btn {\n    padding: 6px 16px;\n    border-radius: 4px;\n    border: 1px solid #dcdfe6;\n    background: #fff;\n    cursor: pointer;\n    font-size: 13px;\n  }\n  .btn.primary {\n    background: #409eff;\n    border-color: #409eff;\n    color: #fff;\n  }\n  .btn:hover {\n    opacity: 0.85;\n  }\n  .hint {\n    margin-top: 12px;\n    color: #909399;\n    font-size: 12px;\n  }\n</style>\n";

export const T_LOWCODE_BOOT = "/**\n * 联邦启动初始化（lowcode 版，乾坤 mount 期行为的联邦等价物）\n *\n * 乾坤时代 lowcode 整应用启动（main.ts setupAll）：i18n / 全局组件 / lowDesagn /\n * avue / hasPermi 指令等全局注册；联邦模式只加载页面组件，这些全部缺失 →\n * \"Failed to resolve component: avue-crud / directive: hasPermi\"。\n *\n * 与 main.ts setupAll 的差异（有意为之）：\n * - i18n 装到一次性空 app：app.use(i18n) 会覆盖宿主（admin）的 $t，不能装到宿主 app；\n * - globCom/lowDesagn/avue/hasPermi 装到宿主 app：组件/指令按 app 维度注册；\n * - 不装 router/store/ElementPlus/vxe 等：页面在宿主 realm 运行，store 由 shared\n *   单例协商，ElementPlus 由页面自身消费。\n *\n * 宿主（admin）联邦页面工厂在 loadRemote 页面前按 remote 记忆化调用。\n * 失败必须显式抛错（H3 零兜底），禁止 warn「跳过」后带缺失的全局注册静默渲染。\n */\nimport type { App } from 'vue'\nimport { createApp } from 'vue'\n// 深路径直取（不走 bare 'element-plus' 的 shared 门面）：bare 导入会经 loadShare 走\n// provider 路径，而 provider 裸门面在 rolldown export*+TLA 下命名绑定全 undefined\n// （见 docs/UNRESOLVED U-6 附记）；深路径直接打包、与页面 EP 同一模块图实例，\n// localeContextKey Symbol 一致，provide 才能被 avue 内部 el-pagination 命中\nimport { provideGlobalConfig } from 'element-plus/es/components/config-provider/src/hooks/use-global-config.mjs'\nimport zhCn from 'element-plus/es/locale/lang/zh-cn'\nimport { setupI18n } from '@/plugins/vueI18n'\nimport { setupGlobCom } from '@/components'\nimport { setupLowDesagn } from '@/plugins/lowDesagn'\nimport { setupAvue } from '@/plugins/avue'\nimport { setupAuth } from '@/directives'\n\nlet booted: Promise<void> | null = null\n\nexport async function federatedBoot(hostApp?: App): Promise<void> {\n  if (!booted) {\n    booted = (async () => {\n      // 一次性空 app 承载 i18n 安装，避免覆盖宿主 $t\n      const i18nHost = createApp({ render: () => null })\n      await setupI18n(i18nHost)\n\n      // 宿主 app 实例：由 admin fulgurBridge 在 loadRemote 前写入 globalThis\n      const target = hostApp ?? (globalThis as any).__FULGUR_HOST_APP__\n      if (!target) {\n        throw new Error('[federatedBoot] 宿主 app 不可用（globalThis.__FULGUR_HOST_APP__ 未写入），无法注册全局组件')\n      }\n      setupGlobCom(target)\n      setupLowDesagn(target)\n      setupAvue(target)\n      setupAuth(target)\n      // EP 全局 locale（乾坤时代 App.vue ConfigGlobal 的联邦等价物）：provideGlobalConfig\n      // 在宿主 app 级同时 provide localeContextKey —— EP shared 单副本后（D.4）Symbol 全页一致，\n      // avue 内部 el-pagination 的 inject 才能命中（否则回落英文 Total/page）；仅 lowcode 副本\n      // Symbol 生效，不影响宿主自身 EP 副本\n      provideGlobalConfig({ locale: zhCn }, target)\n    })().catch((e) => {\n      booted = null\n      throw e\n    })\n  }\n  return booted\n}\n\nexport default federatedBoot\n";

export const T_LOWCODE_INFOCARD = "<template>\n  <div class=\"fulgur-info-card\">\n    <div class=\"card-header\">\n      <span>__LOWCODE_NAME__ 远程组件 InfoCard</span>\n      <span class=\"tag\">联邦直渲染</span>\n    </div>\n    <table class=\"info-table\">\n      <tbody>\n        <tr>\n          <td class=\"label\">来源</td>\n          <td>cku-__LOWCODE_NAME__（/lowcode）</td>\n        </tr>\n        <tr>\n          <td class=\"label\">计数</td>\n          <td>{{ count }}</td>\n        </tr>\n      </tbody>\n    </table>\n    <div class=\"actions\">\n      <button class=\"btn primary\" @click=\"handleAdd\">计数 +1</button>\n    </div>\n    <p class=\"hint\">本组件验证跨应用组件加载与响应式交互。</p>\n  </div>\n</template>\n\n<script lang=\"ts\" setup>\n  import { ref } from 'vue'\n\n  // 注意：exposes 演示组件保持纯 Vue + 原生元素（DESIGN 已知差异 #4 规避①）\n  const count = ref(0)\n\n  const handleAdd = () => {\n    count.value += 1\n  }\n</script>\n\n<style scoped>\n  .fulgur-info-card {\n    width: 420px;\n    padding: 16px;\n    border: 1px solid #dcdfe6;\n    border-radius: 8px;\n    background: #fff;\n    font-size: 14px;\n  }\n  .card-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    font-weight: 600;\n  }\n  .tag {\n    padding: 1px 8px;\n    border-radius: 4px;\n    background: #ecf5ff;\n    color: #409eff;\n    font-size: 12px;\n    font-weight: 400;\n  }\n  .info-table {\n    margin-top: 14px;\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 13px;\n  }\n  .info-table td {\n    border: 1px solid #ebeef5;\n    padding: 6px 10px;\n  }\n  .info-table .label {\n    width: 80px;\n    color: #909399;\n    background: #fafafa;\n  }\n  .actions {\n    margin-top: 14px;\n  }\n  .btn {\n    padding: 6px 16px;\n    border-radius: 4px;\n    border: 1px solid #dcdfe6;\n    background: #fff;\n    cursor: pointer;\n    font-size: 13px;\n  }\n  .btn.primary {\n    background: #409eff;\n    border-color: #409eff;\n    color: #fff;\n  }\n  .btn:hover {\n    opacity: 0.85;\n  }\n  .hint {\n    margin-top: 12px;\n    color: #909399;\n    font-size: 12px;\n  }\n</style>\n";

export const T_BPM_OPTIMIZE = "const include = [\n  'qs',\n  'url',\n  'vue',\n  'sass',\n  'mitt',\n  'axios',\n  'pinia',\n  'qrcode',\n  'unocss',\n  'vue-router',\n  'vue-types',\n  'vue-i18n',\n  'crypto-js',\n  'cropperjs',\n  'lodash-es',\n  'nprogress',\n  'web-storage-cache',\n  '@iconify/iconify',\n  '@vueuse/core',\n  '@zxcvbn-ts/core',\n  'echarts/core',\n  'echarts/charts',\n  'echarts/components',\n  'echarts/renderers',\n  'echarts-wordcloud',\n  '@wangeditor/editor',\n  '@wangeditor/editor-for-vue',\n  '@microsoft/fetch-event-source',\n  'markdown-it',\n  'markmap-view',\n  'markmap-lib',\n  'markmap-toolbar',\n  'highlight.js',\n  '@element-plus/icons-vue',\n]\n\n// 联邦 dev 关键配置（exclude 优先于 include）：element-plus/@element-plus/icons-vue 移出\n// 预构建防其内联本地 vue（双实例 → 页面静默空白）；dayjs 随 EP 移出后其 CJS 子路径由\n// vite.config 的 dev 专用 dayjs→esm 别名兜住；@form-create 系列同理（表单设计器）\nconst exclude = [\n  '@iconify/json',\n  '@element-plus/icons-vue',\n  '@form-create/core',\n  '@form-create/element-ui',\n  '@form-create/designer',\n]\n\nexport { include, exclude }\n";

export const T_LOWCODE_OPTIMIZE = "import MEditor from '../monacoEditor'\n\nconst include = [\n  'qs',\n  'url',\n  'vue',\n  'sass',\n  'mitt',\n  'axios',\n  'pinia',\n  'qrcode',\n  'unocss',\n  'vue-router',\n  'vue-types',\n  'vue-i18n',\n  'crypto-js',\n  'cropperjs',\n  'lodash-es',\n  'nprogress',\n  'web-storage-cache',\n  '@iconify/iconify',\n  '@vueuse/core',\n  '@zxcvbn-ts/core',\n  'echarts/core',\n  'echarts/charts',\n  'echarts/components',\n  'echarts/renderers',\n  'echarts-wordcloud',\n  '@smallwei/avue',\n  '@smallwei/avue/lib/index.css',\n  'monaco-editor/esm/vs/editor/editor.main',\n  'vxe-table/es/vxe-ui/index.js'\n]\n\n// 这些依赖的预构建产物会内联本地 vue，联邦模式下与宿主 vue 实例冲突（双实例），\n// 移出预构建走插件门面改写（@smallwei/avue 仅 UMD 构建，dev 预构建限制见 UNRESOLVED U-2）。\n// dayjs/element-plus 移出预构建后：dev 由 vite.config 的 dayjs→esm 专用别名兜 CJS 子路径\nconst exclude = ['@iconify/json', 'element-plus', 'element-plus/es', 'dayjs']\n\nconst esbuildOptions = {\n  plugins: [\n    //monacoEditor汉化\n    MEditor.esbuildPluginMonacoEditorNls({\n      locale: MEditor.Languages.zh_hans,\n      localeData: MEditor.i18n\n    })\n  ]\n}\n\nexport { include, exclude, esbuildOptions }\n";

export const T_MODULE_DESIGN = "<template>\n  <ContentWrap>\n    <div class=\"flex gap-x-10px\">\n      <div class=\"flex-basis-180px flex-shrink-0\">\n        <avue-tree\n          ref=\"treeRef\"\n          v-model=\"treeForm\"\n          :option=\"treeOption\"\n          :data=\"treeData\"\n          :permission=\"treePermission\"\n          :before-open=\"treeBeforeOpen\"\n          @node-contextmenu=\"treeNodeContextmenu\"\n          @node-click=\"treeNodeClick\"\n          @update=\"treeUpdate\"\n          @save=\"treeSave\"\n          @del=\"treeDel\"\n        >\n        </avue-tree>\n      </div>\n      <avue-crud\n        class=\"table-content flex-1\"\n        ref=\"crudRef\"\n        v-model=\"tableForm\"\n        v-model:page=\"tablePage\"\n        v-model:search=\"tableSearch\"\n        :table-loading=\"loading\"\n        :data=\"tableData\"\n        :option=\"tableOption\"\n        :permission=\"permission\"\n        :before-open=\"beforeOpen\"\n        @search-change=\"searchChange\"\n        @search-reset=\"resetChange\"\n        @row-save=\"rowSave\"\n        @row-update=\"rowUpdate\"\n        @row-del=\"rowDel\"\n        @refresh-change=\"getTableData\"\n        @size-change=\"sizeChange\"\n        @current-change=\"currentChange\"\n        @selection-change=\"selectionChange\"\n      >\n        <template #menu-left=\"{ size }\">\n          <el-dropdown @command=\"menuLeftHandle\" v-hasPermi=\"['jeelowcode:tab:js']\">\n            <el-button type=\"primary\" :size=\"size\" class=\"ml-10px\">\n              <Icon :size=\"14\" icon=\"teenyicons:webpack-outline\" />\n              <span class=\"ml-3px!\">前端增强</span>\n            </el-button>\n            <template #dropdown>\n              <el-dropdown-menu>\n                <el-dropdown-item command=\"js\">JS增强</el-dropdown-item>\n                <el-dropdown-item command=\"scss\">SCSS增强</el-dropdown-item>\n              </el-dropdown-menu>\n            </template>\n          </el-dropdown>\n        </template>\n        <template #menu=\"{ size, row, index }\">\n          <div class=\"flex justify-center flex-items-center\">\n            <el-button\n              type=\"primary\"\n              text\n              :size=\"size\"\n              @click=\"menuHandle({ type: 'edit', row, index })\"\n              v-hasPermi=\"['jeelowcode:tab:update']\"\n            >\n              <Icon :size=\"14\" icon=\"ep:edit-pen\"></Icon>\n              <span>编辑</span>\n            </el-button>\n            <span\n              v-if=\"\n                checkPermi(['jeelowcode:tab:update']) &&\n                checkPermi([\n                  'jeelowcode:tab:create',\n                  'jeelowcode:tab:update',\n                  'jeelowcode:tab:delete'\n                ])\n              \"\n              class=\"ml-8px mr-8px mt-2px inline-block h-16px w-1px bg-#e8e8e8 .dark:bg-[var(--el-border-color-dark)]\"\n            ></span>\n            <el-dropdown\n              @command=\"menuHandle\"\n              v-if=\"\n                checkPermi([\n                  'jeelowcode:tab:create',\n                  'jeelowcode:tab:update',\n                  'jeelowcode:tab:delete'\n                ])\n              \"\n            >\n              <div class=\"mt--2px cursor-pointer\">\n                <el-text :size=\"size\" type=\"primary\">\n                  更多\n                  <Icon :size=\"16\" icon=\"iconamoon:arrow-down-2-light\" />\n                </el-text>\n              </div>\n              <template #dropdown>\n                <el-dropdown-menu>\n                  <el-dropdown-item :command=\"{ type: 'test', row }\"> 功能测试 </el-dropdown-item>\n                  <el-dropdown-item :command=\"{ type: 'routeAddress', row }\">\n                    路由地址\n                  </el-dropdown-item>\n                  <el-dropdown-item\n                    v-if=\"checkPermi(['jeelowcode:tab:update'])\"\n                    :command=\"{ type: 'jsUnlock', row }\"\n                  >\n                    js增强解锁\n                  </el-dropdown-item>\n                  <el-dropdown-item\n                    v-if=\"checkPermi(['jeelowcode:tab:update'])\"\n                    :command=\"{ type: 'scssUnlock', row }\"\n                  >\n                    scss增强解锁\n                  </el-dropdown-item>\n                  <el-dropdown-item\n                    v-if=\"checkPermi(['jeelowcode:tab:delete'])\"\n                    :command=\"{ type: 'del', row }\"\n                  >\n                    删除\n                  </el-dropdown-item>\n                </el-dropdown-menu>\n              </template>\n            </el-dropdown>\n          </div>\n        </template>\n        <template #lowSelectRadio=\"{ row }\">\n          <el-radio\n            class=\"low-select-radio\"\n            v-model=\"radioValue\"\n            :label=\"row.id\"\n            @click=\"radioClick(row)\"\n          />\n        </template>\n        <template #optionList-form>\n          <avue-crud ref=\"moduleCrudRef\" :option=\"moduleOption\" :data=\"tableForm.optionList\">\n            <template #menu=\"{ size, index }\">\n              <el-button text :size=\"size\" type=\"danger\" @click=\"delModuleTableRow(index)\">\n                <span>删除</span>\n              </el-button>\n            </template>\n            <template #darg=\"{ index }\">\n              <el-dropdown trigger=\"hover\" placement=\"bottom\" @command=\"dropdownCommand\">\n                <div>\n                  <Icon :size=\"20\" icon=\"gg:menu-grid-r\" />\n                </div>\n                <template #dropdown>\n                  <el-dropdown-menu>\n                    <el-dropdown-item :command=\"{ index: index, type: 'up' }\" :disabled=\"index == 0\"\n                      >向上移</el-dropdown-item\n                    >\n                    <el-dropdown-item\n                      :command=\"{ index: index, type: 'down' }\"\n                      :disabled=\"index == tableForm.optionList?.length - 1\"\n                      >向下移</el-dropdown-item\n                    >\n                    <el-dropdown-item :command=\"{ index: index, type: 'add' }\"\n                      >插入一行</el-dropdown-item\n                    >\n                  </el-dropdown-menu>\n                </template>\n              </el-dropdown>\n            </template>\n            <template #tabIcon=\"{ row }\">\n              <Icon v-if=\"row.tabIcon\" :size=\"14\" :icon=\"row.tabIcon\" />\n            </template>\n            <template #tabIcon-form=\"{ row, column, size, disabled }\">\n              <IconSelectInput\n                v-model=\"row.tabIcon\"\n                :prop=\"column.prop\"\n                :column=\"column\"\n                :size=\"size\"\n                :disabled=\"disabled\"\n              />\n            </template>\n            <template #moduleValue-form=\"{ row }\">\n              <avue-select\n                v-if=\"row.moduleType == 'table'\"\n                v-model=\"row.moduleValue\"\n                placeholder=\"请选择表单开发配置\"\n                :dic=\"tableDicData\"\n                :virtualize=\"true\"\n                :filterable=\"true\"\n              ></avue-select>\n              <avue-select\n                v-else-if=\"row.moduleType == 'form'\"\n                v-model=\"row.moduleValue\"\n                placeholder=\"请选择自定义表单配置\"\n                :dic=\"formDicData\"\n                :virtualize=\"true\"\n                :filterable=\"true\"\n              ></avue-select>\n              <avue-select\n                v-else-if=\"row.moduleType == 'report'\"\n                v-model=\"row.moduleValue\"\n                placeholder=\"请选择报表配置\"\n                :dic=\"reportDicData\"\n                :virtualize=\"true\"\n                :filterable=\"true\"\n              ></avue-select>\n              <avue-input\n                v-else-if=\"row.moduleType == 'custom'\"\n                v-model=\"row.moduleValue\"\n                placeholder=\"模块所在文件路径\"\n                prepend=\"src/\"\n              >\n              </avue-input>\n            </template>\n            <template #isLazy-header=\"{ column }\">\n              <span>{{ column.label }}</span>\n              <div class=\"pos-absolute right-1px top-0\">\n                <el-tooltip\n                  class=\"box-item\"\n                  effect=\"dark\"\n                  content=\"第一次切换到当前标签页之前模块内容都不会加载\"\n                  placement=\"top-start\"\n                >\n                  <Icon :size=\"14\" icon=\"ep:info-filled\"></Icon>\n                </el-tooltip>\n              </div>\n            </template>\n            <template #isLazy-form=\"{ row }\">\n              <el-checkbox v-model=\"row.isLazy\" true-value=\"Y\" false-value=\"N\" />\n            </template>\n            <template #isRefresh-header=\"{ column }\">\n              <span>{{ column.label }}</span>\n              <div class=\"pos-absolute right-1px top-0\">\n                <el-tooltip\n                  class=\"box-item\"\n                  effect=\"dark\"\n                  content=\"切换到当前标签页时，会刷新当前模块内容的数据\"\n                  placement=\"top-start\"\n                >\n                  <Icon :size=\"14\" icon=\"ep:info-filled\"></Icon>\n                </el-tooltip>\n              </div>\n            </template>\n            <template #isRefresh-form=\"{ row }\">\n              <el-checkbox v-model=\"row.isRefresh\" true-value=\"Y\" false-value=\"N\" />\n            </template>\n            <template #tabI18n-form=\"{ row }\">\n              <I18nInput v-model=\"row.tabI18n\" :def-name=\"row.tabName\"></I18nInput>\n            </template>\n          </avue-crud>\n        </template>\n      </avue-crud>\n    </div>\n    <DesignPopup v-model=\"MEDialog.value\" v-bind=\"MEDialog.params\" :isBodyFull=\"true\">\n      <template #default>\n        <el-container class=\"h-100%\">\n          <el-main class=\"p-0!\">\n            <MonacoEditor\n              class=\"flex-1\"\n              v-model=\"MEData.value\"\n              v-bind=\"MEData.params\"\n            ></MonacoEditor>\n          </el-main>\n          <el-aside width=\"300px\" v-if=\"MEDialog.otherParams\">\n            <TipView v-bind=\"MEDialog.otherParams\"></TipView>\n          </el-aside>\n        </el-container>\n      </template>\n    </DesignPopup>\n    <DesignPopup v-model=\"samplePopup\" title=\"控件使用示例\" :width=\"280\">\n      <template #default>\n        <div class=\"text-center p-20px\">\n          <div class=\"b b-b-0 b-solid b-#f1f1f1 .dark:b-[var(--el-border-color-dark)]\">\n            <div\n              v-for=\"(item, key) in controlPath\"\n              :key=\"key\"\n              class=\"h-50px flex items-center b-b b-b-solid b-#f1f1f1 .dark:b-[var(--el-border-color-dark)] pr-10px\"\n            >\n              <div class=\"text-14px flex-1\">{{ item.name }}</div>\n              <el-button\n                class=\"flex-basis-80px flex-shrink-0\"\n                size=\"small\"\n                type=\"primary\"\n                @click=\"copySampleStr(key)\"\n                >点击复制</el-button\n              >\n            </div>\n          </div>\n        </div>\n      </template>\n    </DesignPopup>\n  </ContentWrap>\n</template>\n<script lang=\"ts\" setup>\nimport { TipView } from '../general/components/index'\nimport * as ModuleApi from '@/api/design/module'\nimport * as FormApi from '@/api/design/form'\nimport * as TableApi from '@/api/design/table'\nimport * as ReportApi from '@/api/design/report'\nimport { ElLoading } from 'element-plus'\nimport { cloneDeep } from 'lodash-es'\nimport { useGroup } from '@/hooks/design/useGroup'\nimport { checkPermi } from '@/utils/permission'\nimport { ElButton } from 'element-plus'\nimport { I18nInput } from '@/components/LowDesign/src/shareControl/index'\nimport controlPath from '@/components/LowDesign/src/controlPath'\nimport useCopyText from '@/hooks/design/useCopyText'\nimport useMEDialog from '@/hooks/design/useMEDialog'\nimport {\n  moduleScssEnhanceExample,\n  controlInitExample\n} from '@/components/LowDesign/src/utils/example'\nimport { formattingLengStr } from '@/utils/lowDesign'\ndefineOptions({ name: 'FormDesign' })\n\nconst message = useMessage() // 消息弹窗\nconst { t } = useI18n() // 国际化\nconst router = useRouter() // 路由\nconst { getCurrPermi } = useCrudPermi()\nconst { copyText } = useCopyText()\nconst { MEDialog, MEData, openMEDialog } = useMEDialog()\nconst loading = ref(true) // 列表的加载中\n//表格配置\nconst tabsType = [\n  { label: '默认风格', value: 'default' },\n  { label: '卡片风格', value: 'card' },\n  { label: '带边框的卡片风格', value: 'border-card' }\n]\nconst tabsPosition = [\n  { label: '上边', value: 'top' },\n  { label: '左边', value: 'left' },\n  { label: '右边', value: 'right' },\n  { label: '下边', value: 'bottom' }\n]\nconst moduleType = [\n  { label: '表单开发', value: 'table' },\n  { label: '自定义表单', value: 'form' },\n  { label: '报表设计', value: 'report' },\n  { label: '自定义模块', value: 'custom' }\n]\nconst getRules = (label, type?) => {\n  return [\n    {\n      required: true,\n      message: (type == 'select' ? '请选择' : '请输入') + label,\n      trigger: type == 'select' ? 'change' : 'blur'\n    }\n  ]\n}\nconst tableOption = ref({\n  align: 'center',\n  headerAlign: 'center',\n  searchMenuSpan: 6,\n  searchMenuPosition: 'left',\n  labelSuffix: ' ',\n  dialogWidth: '90%',\n  dialogFullscreen: false,\n  dialogCustomClass: 'tabs-design-form',\n  editBtn: false,\n  delBtn: false,\n  border: true,\n  index: false,\n  menuWidth: 180,\n  span: 12,\n  column: {\n    lowSelectRadio: {\n      label: '',\n      display: false,\n      width: 50,\n      overHidden: false,\n      fixed: true,\n      showColumn: false\n    },\n    id: { label: '模块id', display: false, search: true, overHidden: true, width: 170 },\n    moduleName: { label: '模块名称', display: false, search: true, overHidden: true },\n    tabsType: { label: '风格类型', display: false, type: 'select', dicData: tabsType, width: 140 },\n    tabsPosition: {\n      label: '选项卡位置',\n      display: false,\n      type: 'select',\n      dicData: tabsPosition,\n      width: 120\n    },\n    updateTime: {\n      label: '修改时间',\n      type: 'datetime',\n      format: 'YYYY-MM-DD HH:mm:ss',\n      valueFormat: 'x',\n      display: false,\n      width: 160\n    }\n  },\n  group: [\n    {\n      label: '基本信息',\n      collapse: true,\n      prop: 'group_info',\n      column: {\n        moduleName: { label: '模块名称', rules: getRules('模块名称') },\n        groupModuleId: {\n          label: '分组类型',\n          type: 'tree',\n          value: '',\n          dicData: [],\n          filterable: true,\n          defaultExpandAll: true,\n          props: { label: 'name', value: 'id' }\n        },\n        tabsType: {\n          label: '风格类型',\n          type: 'select',\n          dicData: tabsType,\n          value: 'border-card',\n          clearable: false\n        },\n        tabsPosition: {\n          label: '选项卡位置',\n          type: 'select',\n          dicData: tabsPosition,\n          value: 'top',\n          clearable: false\n        }\n      }\n    },\n    {\n      label: '模块配置',\n      collapse: true,\n      prop: 'group_module',\n      labelWidth: 20,\n      column: {\n        optionList: {\n          hide: false,\n          span: 24,\n          dataType: 'array',\n          value: [\n            {\n              $cellEdit: true,\n              tabName: '',\n              tabCode: '',\n              moduleType: 'table',\n              moduleValue: '',\n              tabIcon: '',\n              isLazy: false,\n              isRefresh: false\n            }\n          ],\n          rules: [\n            {\n              validator: (rule, value, callback) => {\n                if (value?.length) callback()\n                else callback(new Error('请添加模块信息'))\n              },\n              trigger: 'blur'\n            }\n          ]\n        }\n      }\n    }\n  ]\n})\nconst tableForm = ref<any>({})\nconst tableData = ref([])\nconst tableSearch = ref({})\nconst tablePage = ref({\n  currentPage: 1,\n  pageSize: 10,\n  total: 0\n})\nconst tableSelect = ref<any[]>([])\nconst radioValue = ref('')\nconst jsEnhanceData = ref({})\nconst designPop = ref({\n  value: {},\n  dialog: false,\n  params: {}\n})\n\nconst moduleOption = ref({\n  addBtn: false,\n  editBtn: false,\n  addRowBtn: true,\n  refreshBtn: false,\n  columnBtn: false,\n  addBtnText: '新增模块',\n  menuWidth: 70,\n  height: undefined,\n  calcHeight: undefined,\n  maxHeight: 300,\n  index: true,\n  column: {\n    darg: { width: 45 },\n    tabName: { label: '标签名称', cell: true, minWidth: 150, rules: getRules('标签名称') },\n    tabCode: { label: '标签编码', cell: true, width: 150, rules: getRules('标签名称') },\n    moduleType: {\n      label: '模块类型',\n      type: 'select',\n      dicData: moduleType,\n      value: 'table',\n      cell: true,\n      width: 140,\n      clearable: false\n    },\n    moduleValue: {\n      label: '模块内容',\n      cell: true,\n      minWidth: 180,\n      rules: getRules('模块内容', 'select')\n    },\n    tabI18n: { label: '国际化配置', cell: true, width: 100 },\n    tabIcon: { label: '标签图标', cell: true, width: 140 },\n    isLazy: { label: '懒加载', cell: true, width: 70, value: 'N' },\n    isRefresh: { label: '刷新数据', cell: true, width: 85, value: 'N' }\n  }\n})\n\nconst tableDicData = ref([])\nconst formDicData = ref([])\nconst reportDicData = ref([])\nconst samplePopup = ref(false)\n\nconst crudRef = ref()\nconst treeRef = ref()\n\nconst isUnload = ref(false)\n\nconst permission = getCurrPermi(['jeelowcode:tab'])\nuseCrudHeight(crudRef)\nconst {\n  treeForm,\n  treeOption,\n  treeData,\n  groupValue,\n  treePermission,\n  treeBeforeOpen,\n  treeNodeContextmenu,\n  treeNodeClick,\n  getTreeData,\n  treeUpdate,\n  treeSave,\n  treeDel\n} = useGroup(treeRef, ModuleApi, () => resetChange())\n\nconst radioClick = (row) => {\n  if (row.id == radioValue.value) {\n    setTimeout(() => {\n      radioValue.value = ''\n      tableSelect.value = []\n    }, 30)\n  } else {\n    tableSelect.value = [row]\n  }\n}\n\nconst delModuleTableRow = (index) => {\n  tableForm.value.optionList.splice(index, 1)\n}\n\nconst menuLeftHandle = (type) => {\n  if (['js', 'scss'].includes(type) && tableSelect.value.length !== 1) {\n    return message.warning('请勾选一条表格数据')\n  }\n  if (['js', 'scss'].includes(type)) openModuleEnhance(type)\n}\n\nconst dropdownCommand = ({ index, type }) => {\n  if (type == 'up' || type == 'down') {\n    const delItem = tableForm.value.optionList.splice(index, 1)[0]\n    nextTick(() =>\n      tableForm.value.optionList.splice(type == 'up' ? index - 1 : index + 1, 0, delItem)\n    )\n  } else if (type == 'add') {\n    tableForm.value.optionList.splice(index + 1, 0, { $cellEdit: true, moduleType: 'table' })\n  }\n}\n\nconst handleWebEnhance = (moduleId, enhanceType) => {\n  return new Promise(async (resolve) => {\n    let apiType = 'updateJsData'\n    let apiData = {\n      id: jsEnhanceData.value['id'],\n      tabId: moduleId,\n      jsType: enhanceType,\n      jsJson: MEData.value.value\n    }\n    if (!apiData.id) {\n      apiType = 'saveJsData'\n      delete apiData.id\n    }\n    const data = await ModuleApi[apiType](apiData).catch(() => false)\n    if (data) message.success('保存成功')\n    resolve(data)\n  })\n}\n\nconst getAllDic = () => {\n  // 三处形状守卫：字典接口返回异常形状（如 graphreport success:false 时拦截器返回\n  // 非 records 结构）时置空数组，不向用户抛 TypeError（与 H1 零报错口径一致）\n  TableApi.getAllDbDicData({ onlyTableName: 'Y' }).then(async (res) => {\n    tableDicData.value = (Array.isArray(res) ? res : []).map((item) => {\n      return { label: `${item.tableDescribe}[${item.tableName}]`, value: item.tableId }\n    })\n  })\n  FormApi.getFormList({}).then((res) => {\n    formDicData.value = (Array.isArray(res?.records) ? res.records : []).map((item) => {\n      return { label: item.desformName, value: item.id }\n    })\n  })\n  ReportApi.getDbList({}).then((res) => {\n    reportDicData.value = (Array.isArray(res?.records) ? res.records : []).map((item) => {\n      return { label: item.reportName, value: item.reportCode }\n    })\n  })\n}\n\nconst menuHandle = async ({ type, row, index }) => {\n  if (type == 'edit') crudRef.value.rowEdit(row, index)\n  else if (type == 'test') router.push({ path: '/low/module/test/' + row.id })\n  else if (type == 'routeAddress') showRouteAddress(row)\n  else if (type.indexOf('Unlock') != -1) unlockEnhance(type, row)\n  else if (type == 'del') rowDel(row)\n}\n\nconst showRouteAddress = (row) => {\n  const url = `module/view/` + row.id\n  message.alert(`路由地址：</br>${url}`, '菜单的路由地址', {\n    confirmButtonText: '复制',\n    dangerouslyUseHTMLString: true,\n    callback: (action) => {\n      if (action == 'confirm') copyText(url)\n    }\n  })\n}\n\nconst unlockEnhance = (type, row) => {\n  const enhanceType = type.split('Unlock')[0]\n  message.confirm(`是否强制解除${enhanceType}增强锁定？`, '提示').then(async () => {\n    await ModuleApi.unlockJs(row.id, enhanceType)\n    message.success('解除锁定成功')\n    if (type.indexOf('Open') !== -1 && tableSelect.value.length) menuLeftHandle(enhanceType)\n  })\n}\n\nconst openModuleEnhance = async (enhanceType) => {\n  loading.value = true\n  jsEnhanceData.value = { jsJson: '' }\n  const moduleId = tableSelect.value[0].id\n  const detailData = await ModuleApi.getJsDetail({\n    tabId: moduleId,\n    type: enhanceType,\n    lock: true\n  }).catch(() => false)\n  loading.value = false\n  if (detailData === false) return\n  if (detailData) {\n    if (detailData.timeStr) {\n      message\n        .confirm(\n          `<div>\n        <div style=\"font-size:16px\"><span style=\"font-size:14px\">锁定操作人：</span>${detailData.userName}</div>\n        <div style=\"font-size:16px\"><span style=\"font-size:14px\">开始锁定时间：</span>${detailData.timeStr}</div>\n        <div style=\"color:#E6A23C\">注：如果确认没有人正在编辑，可点击下方强制解锁</div>\n      </div>`,\n          '当前增强已锁定',\n          {\n            dangerouslyUseHTMLString: true,\n            cancelButtonText: '关闭',\n            confirmButtonText: '强制解锁'\n          }\n        )\n        .then(() => {\n          menuHandle({\n            type: `${enhanceType}UnlockOpen`,\n            row: tableSelect.value[0],\n            index: tableSelect.value[0].$index\n          })\n        })\n      return\n    }\n    if (detailData.jsJson) {\n      jsEnhanceData.value = detailData\n    }\n  }\n  let params = {\n    title: `${enhanceType}增强 【${tableSelect.value[0].moduleName}】`,\n    fullscreen: true,\n    handleClose: async (done) => {\n      await ModuleApi.unlockJs(moduleId, enhanceType)\n      isUnload.value = false\n      done()\n    },\n    footerBtn: [\n      {\n        params: { type: 'primary' },\n        name: '保 存',\n        icon: 'mingcute:save-line',\n        loading: true,\n        clickFun: async (loading) => {\n          const id = await handleWebEnhance(moduleId, enhanceType)\n          if (id) jsEnhanceData.value['id'] = id\n          loading()\n        }\n      },\n      {\n        params: { type: 'success' },\n        name: '保存并关闭',\n        icon: 'mingcute:save-line',\n        loading: true,\n        clickFun: async (loading) => {\n          const bool = await handleWebEnhance(moduleId, enhanceType)\n          await ModuleApi.unlockJs(moduleId, enhanceType)\n          loading()\n          if (bool) {\n            MEDialog.value.value = false\n            isUnload.value = false\n          }\n        }\n      },\n      {\n        params: {},\n        name: '关 闭',\n        icon: 'material-symbols:close',\n        clickFun: async () => {\n          await message.confirm('是否确认关闭？')\n          await ModuleApi.unlockJs(moduleId, enhanceType)\n          MEDialog.value.value = false\n          isUnload.value = false\n        }\n      }\n    ]\n  }\n  if (enhanceType == 'js') {\n    params['providerType'] = 'moduleJsEnhance'\n    params['otherParams'] = { type: 'simple', width: '300px', tipKeyList: ['ModuleJsEnhance'] }\n    params['language'] = 'javascript'\n    params['headerBtn'] = [\n      {\n        params: { type: 'success' },\n        name: '控件使用示例',\n        icon: 'jam:code-sample',\n        clickFun: async () => (samplePopup.value = true)\n      }\n    ]\n    if (!jsEnhanceData.value['jsJson']) {\n      jsEnhanceData.value['jsJson'] = `return {\n\n}`\n    }\n  } else if (enhanceType == 'scss') {\n    params['language'] = 'scss'\n    if (!jsEnhanceData.value['jsJson']) {\n      jsEnhanceData.value['jsJson'] = moduleScssEnhanceExample(moduleId)\n    }\n  }\n\n  openMEDialog({ params, prop: 'jsJson' }, jsEnhanceData.value)\n  isUnload.value = true\n}\n\nconst copySampleStr = (type) => {\n  copyText(controlInitExample(type))\n  samplePopup.value = false\n}\n\nconst selectionChange = (data) => {\n  tableSelect.value = data\n}\n\n/** 查询列表 */\nconst getTableData = async () => {\n  loading.value = true\n  let searchObj = {\n    ...tableSearch.value,\n    pageNo: tablePage.value.currentPage,\n    pageSize: tablePage.value.pageSize\n  }\n  if (groupValue.value) searchObj['groupModuleId'] = groupValue.value\n  for (let key in searchObj) if (searchObj[key] === '') delete searchObj[key]\n  try {\n    const data = await ModuleApi.getModuleList(searchObj)\n    // 形状守卫：后台缺 /tab/page 端点（404 → axios 拒绝）或返回异常形状时，\n    // 空态渲染而非 TypeError；失败经 console.warn 显式可见（不静默吞）\n    tableData.value = Array.isArray(data?.records) ? data.records : []\n    tablePage.value.total = data?.total ?? 0\n  } catch (e) {\n    tableData.value = []\n    tablePage.value.total = 0\n    console.warn('[moduleDesign] 模块列表加载失败（本地后台无 /tab/page 端点或缺接口权限）:', e)\n  } finally {\n    loading.value = false\n  }\n}\n\n/** 搜索按钮操作 */\nconst searchChange = (params, done) => {\n  if (Object.keys(params).length && groupValue.value) {\n    treeRef.value.setCurrentKey(0)\n    groupValue.value = 0\n  }\n  tablePage.value.currentPage = 1\n  getTableData().finally(() => {\n    done()\n  })\n}\n\n/** 清空按钮操作 */\nconst resetChange = () => {\n  searchChange({}, () => {})\n}\n\nconst sizeChange = (pageSize) => {\n  tablePage.value.pageSize = pageSize\n  resetChange()\n}\n\nconst currentChange = (currentPage) => {\n  tablePage.value.currentPage = currentPage\n  getTableData()\n}\n\n/** 表单打开前 */\nconst beforeOpen = async (done, type) => {\n  const groupData = cloneDeep(treeData.value)\n  const groupModuleId = tableOption.value.group[0].column.groupModuleId\n  if (groupModuleId) groupModuleId.dicData = groupData[0].children\n  if (['edit', 'view'].includes(type) && tableForm.value['id']) {\n    loading.value = true\n    const data = await ModuleApi.getModuleDetail(tableForm.value['id'])\n    tableForm.value = {\n      ...data.tab,\n      optionList: data.optionList.map((item) => {\n        if (type == 'edit') item.$cellEdit = true\n        return item\n      })\n    }\n    loading.value = false\n  }\n  if (type == 'add' && groupValue.value) {\n    tableForm.value.groupModuleId = groupValue.value\n  }\n  done()\n}\n\nconst initI18nData = (list) => {\n  if (!list?.length) return []\n  return list.map((item) => {\n    item.tabI18n = formattingLengStr(item.tabI18n, item.tabName)\n    return item\n  })\n}\n\n/** 新增操作 */\nconst rowSave = async (form: object, done, loading, isId?) => {\n  const elLoading = ElLoading.service({ fullscreen: true })\n  const saveData = { tab: { ...form }, optionList: initI18nData(form['optionList']) }\n  delete saveData.tab['optionList']\n  let bool = await ModuleApi.saveModuleData(saveData).catch(() => false)\n  if (bool) {\n    message.success(t('common.createSuccess'))\n    resetChange()\n    if (isId) done(bool)\n    else done()\n  } else loading()\n  elLoading.close()\n}\n\n/** 编辑操作 */\nconst rowUpdate = async (form, index, done, loading, onData?) => {\n  const editData = { tab: { ...form }, optionList: initI18nData(form['optionList']) }\n  delete editData.tab['optionList']\n  let bool = await ModuleApi.updateModuleData(editData).catch(() => false)\n  if (bool) {\n    message.success(t('common.updateSuccess'))\n    if (!onData) getTableData()\n    done()\n  } else loading()\n}\n\n/** 删除按钮操作 */\nconst rowDel = async (data) => {\n  try {\n    // 删除的二次确认\n    await message.delConfirm()\n    // 发起删除\n    await ModuleApi.deleteModuleData(data instanceof Array ? data : [data.id])\n    message.success(t('common.delSuccess'))\n    // 刷新列表\n    await getTableData()\n  } catch {}\n}\n\nconst beforeUnload = (event) => {\n  if (isUnload.value) return (event.returnValue = '您确定要关闭页面吗？')\n}\n\n/** 初始化 **/\nonMounted(async () => {\n  window.addEventListener('beforeunload', beforeUnload)\n  getTableData()\n  getTreeData()\n  getAllDic()\n})\n\nonBeforeUnmount(() => {\n  window.removeEventListener('beforeunload', beforeUnload)\n})\n</script>\n\n<style lang=\"scss\" scoped>\n.table-content {\n  max-width: calc(100% - 190px);\n}\n</style>\n<style lang=\"scss\">\n.form-design-address-box {\n  .el-message-box__container {\n    display: block;\n  }\n}\n</style>\n<style lang=\"scss\">\n.tabs-design-form {\n  .el-dialog__body {\n    padding-top: 0 !important;\n  }\n\n  .avue-crud {\n    .avue-crud__empty {\n      padding: 0;\n\n      .el-empty {\n        padding: 0;\n      }\n\n      .el-empty__description {\n        margin: 0;\n      }\n    }\n  }\n}\n</style>\n";
